import * as React from 'react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { render, screen, cleanup, act, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { afterEach, beforeEach, expect, test } from 'vitest';

import { App } from './App';
import { useStoredTheme } from './theme';

function Root() {
  const [theme, setTheme] = useStoredTheme();
  return (
    <ThemeProvider theme={theme}>
      <App theme={theme} onThemeChange={setTheme} />
    </ThemeProvider>
  );
}

beforeEach(() => {
  window.localStorage.clear();
  window.location.hash = '';
  document.body.className = '';
});
afterEach(cleanup);

const heading = () => screen.getByRole('heading', { level: 1 }).textContent;

test('navigation between pages via hash', async () => {
  const user = userEvent.setup();
  render(<Root />);
  expect(heading()).toBe('Главная');

  await user.click(screen.getByRole('tab', { name: 'Заметки' }));
  await waitFor(() => expect(heading()).toBe('Заметки'));
  expect(window.location.hash).toBe('#/notes');

  await user.type(screen.getByPlaceholderText('Новая заметка'), 'Смоук-тест');
  await user.click(screen.getByRole('button', { name: 'Добавить' }));
  expect(screen.getByText('Смоук-тест')).toBeTruthy();
  const removeButtons = screen.getAllByRole('button', { name: 'Удалить' });
  await user.click(removeButtons[removeButtons.length - 1]);
  expect(screen.queryByText('Смоук-тест')).toBeNull();

  await user.click(screen.getByRole('tab', { name: 'О приложении' }));
  await waitFor(() => expect(heading()).toBe('О приложении'));
  expect(window.location.hash).toBe('#/about');

  act(() => { window.location.hash = '#/nope'; });
  await waitFor(() => expect(heading()).toBe('Страница не найдена'));
  await user.click(screen.getByRole('link', { name: 'На главную' }));
  await waitFor(() => expect(heading()).toBe('Главная'));
});

test('theme toggle switches body class and persists', async () => {
  const user = userEvent.setup();
  const { unmount } = render(<Root />);
  expect(document.body.className).toContain('g-root_theme_light');

  await user.click(screen.getByRole('button', { name: 'Включить тёмную тему' }));
  expect(document.body.className).toContain('g-root_theme_dark');
  expect(window.localStorage.getItem('app-theme')).toBe('dark');

  unmount();
  render(<Root />);
  expect(document.body.className).toContain('g-root_theme_dark');
  await user.click(screen.getByRole('button', { name: 'Включить светлую тему' }));
  expect(document.body.className).toContain('g-root_theme_light');
  expect(window.localStorage.getItem('app-theme')).toBe('light');
});
